            ? provider.reviewThreads(item.prNumber) : null;
        if (!(th && th.total > 0 && th.unresolved === 0)) return false;
    } else if (q.threadsResolved === false) {
        var tho = (provider && provider.reviewThreads)
            ? provider.reviewThreads(item.prNumber) : null;
        if (!(tho && tho.unresolved > 0)) return false;
    }
