    // 'none' or 'pending' — validate-fresh matches both.
    var rollup = function (pr) { return pr ? (pr.checkConclusion || pr.checks) : undefined; };
    var rollupWant = function (want) {
        return Array.isArray(want) ? want : (want ? [want] : null);
    };
