      "scm": {
        "provider": "github"
      },
      "dryRun": false,
      "maxConcurrentRuns": 1,
      "maxReworkRounds": 2,
      "workflowFile": "ai-teammate.yml",
      "branchPrefix": "ai/gh-",
      "agentHandle": "ai-teammate",
