function isGlobalWorkflowCapReached(scm, workflowFile, options) {
    options = options || {};
    var cap = resolveActiveWorkflowCap(options);
    if (!cap) return false;

    var active = collectActiveWorkflowRuns(scm, workflowFile, options.owner, options.repo);
